u16 rgb8To16(int r, int g, int b) {
    return ARGB16(1, (r >> 3) & 31, (g >> 3) & 31, (b >> 3) & 31);
}

#define C16(r,g,b) (0x8000 | (((b)>>3)<<10) | (((g)>>3)<<5) | ((r)>>3))

